SELECT DATE_FORMAT(created_at,'%H:%i') AS ksa_minute, COUNT(*) AS events, COUNT(DISTINCT symbol) AS symbols, ROUND(AVG(TIMESTAMPDIFF(MICROSECOND, observed_at, created_at))/1000,1) AS avg_ms, ROUND(MIN(TIMESTAMPDIFF(MICROSECOND, observed_at, created_at))/1000,1) AS min_ms, MIN(created_at) AS first_ksa, MAX(created_at) AS last_ksa FROM market_price_event WHERE id BETWEEN 1455000 AND 1500000 AND created_at BETWEEN '2026-10-11 02:15:00' AND '2026-10-11 03:05:00' GROUP BY ksa_minute ORDER BY ksa_minute